+    // Apply holder would refuse (the lengths, the fit on the tool).
+    let shank_ok = stored.as_ref().is_some_and(|t| {
+        holder_library::resolve(&entry, t.shank_d).and_then(|e| e.fits_shank(t.shank_d)).is_ok()
+    });
